const $ = id => document.getElementById(id);
const {norm,collectorId,numberFrom,similarity,edition,finish,shadowless,duplicateKey,variantLabel,validateBackup}=PokeCore;
function priceQuote(...args){return PokeCore.priceQuote(...args);}
const KEY='pokescan.collection.v1', ALBUM_KEY='pokescan.albums.v1', EXTRA_KEY='pokescan.extras.v1';
const uid=()=>crypto.randomUUID?.() || Date.now()+'-'+Math.random();
function money(n){return Number(n).toLocaleString(typeof PokeLocale!=='undefined'?PokeLocale.current:'de',{style:'currency',currency:'EUR'});}
function dateText(d){return d&&!Number.isNaN(Date.parse(d))?new Date(d).toLocaleDateString(typeof PokeLocale!=='undefined'?PokeLocale.current:'de'):'Unbekannt';}
function create(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function icon(name){const el=document.createElementNS('http://www.w3.org/2000/svg','svg');el.setAttribute('class','ico');el.setAttribute('aria-hidden','true');const use=document.createElementNS(el.namespaceURI,'use');use.setAttribute('href','#ic-'+name);el.append(use);return el;}
function safeParse(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let cards=safeParse(KEY,[]),albums=safeParse(ALBUM_KEY,[]),extras=safeParse(EXTRA_KEY,{});
if(!Array.isArray(cards))cards=[];if(!Array.isArray(albums))albums=[];
function cleanExtras(value){
 const v=value&&typeof value==='object'?value:{},p=v.profile&&typeof v.profile==='object'?v.profile:{};
 const text=(x,n)=>typeof x==='string'?x.slice(0,n):'';
 const history={};for(const [id,list]of Object.entries(v.history||{}))if(!['__proto__','constructor','prototype'].includes(id)&&Array.isArray(list))history[id]=list.filter(h=>h&&typeof h.action==='string'&&typeof h.at==='string').slice(0,50);
 return {...v,profile:{...p,name:text(p.name,32)||'Sammler',bio:text(p.bio,240),theme:['violet','blue','green','rose','gold','teal','orange','slate','red','cyan','lime','indigo','peach','custom'].includes(p.theme)?p.theme:'violet',appearance:['dark','light','system'].includes(p.appearance)?p.appearance:'dark',avatar:typeof p.avatar==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(p.avatar)&&p.avatar.length<200000?p.avatar:null},wishlist:PokeOrganizer.dedupe((Array.isArray(v.wishlist)?v.wishlist:[]).slice(0,2000)).map(w=>({...w,id:w.id||uid()})),history};
}
extras=cleanExtras(extras);
let filter='all',duplicateMode=false,currentView='home',currentAlbum=null,binderMode=false,binderIndex=0,detailId=null,imageSide='official';
let activePhoto=null,selected=null,quote=null,scanFiles=[],scanIndex=0,candidates=[],lastOCR={raw:''},searchToken=0,photoEpoch=0,visualToken=0;
let draftDirty=false,savingCard=false,albumEditId=null,albumPickId=null,cropBitmap=null,pendingProfileAvatar=null;
function toast(message,action){const el=$('toast');el.replaceChildren(create('span','',message));if(action){const b=create('button','',action.label);b.type='button';b.onclick=()=>{action.run();el.classList.remove('visible');};el.append(b);}el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),action?15000:4200);}
function persist(nextCards=cards,nextAlbums=albums,nextExtras=extras){
  const pairs=[[KEY,JSON.stringify(nextCards)],[ALBUM_KEY,JSON.stringify(nextAlbums)],[EXTRA_KEY,JSON.stringify(nextExtras)]];
  let before;
  try{before=pairs.map(([k])=>localStorage.getItem(k));for(const [k,v]of pairs)localStorage.setItem(k,v);return true;}
  catch{if(before)for(let i=0;i<pairs.length;i++)try{if(before[i]===null)localStorage.removeItem(pairs[i][0]);else localStorage.setItem(pairs[i][0],before[i]);}catch{}toast('Speichern fehlgeschlagen. Speicher prüfen und Backup erstellen.');return false;}
}
function commit(nextCards=cards,nextAlbums=albums,nextExtras=extras){if(!persist(nextCards,nextAlbums,nextExtras))return false;cards=nextCards;albums=nextAlbums;extras=nextExtras;render();return true;}
function historyFor(c,action,nextExtras=structuredClone(extras)){const history=Array.isArray(nextExtras.history[c.id])?nextExtras.history[c.id]:[];nextExtras.history[c.id]=[{at:new Date().toISOString(),action},...history].slice(0,50);return nextExtras;}
function confirmAction(title,message,accept='Bestätigen'){
  return new Promise(resolve=>{const dialog=$('confirmDialog');$('confirmTitle').textContent=title;$('confirmText').textContent=message;$('confirmAccept').textContent=accept;let answer=false;const done=()=>{dialog.removeEventListener('close',done);resolve(answer);};dialog.addEventListener('close',done);$('confirmAccept').onclick=()=>{answer=true;dialog.close();};$('confirmCancel').onclick=()=>dialog.close();dialog.showModal();});
}
const photoDB=new Promise(resolve=>{try{const req=indexedDB.open('pokescan-photos',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('photos'))req.result.createObjectStore('photos');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);req.onblocked=()=>resolve(null);}catch{resolve(null);}});
async function photoTransaction(mode,run){const db=await photoDB;if(!db)throw Error('Fotospeicher nicht verfügbar');return new Promise((resolve,reject)=>{const tx=db.transaction('photos',mode),store=tx.objectStore('photos');let result;try{result=run(store);}catch(err){tx.abort();reject(err);return;}tx.oncomplete=()=>resolve(result?.result);tx.onerror=()=>reject(tx.error||Error('Fototransaktion fehlgeschlagen'));tx.onabort=()=>reject(tx.error||Error('Fototransaktion abgebrochen'));});}
const putPhoto=(id,file)=>photoTransaction('readwrite',store=>store.put(file,id));
const getPhoto=id=>id?photoTransaction('readonly',store=>store.get(id)).catch(()=>null):Promise.resolve(null);
const deletePhoto=id=>id?photoTransaction('readwrite',store=>store.delete(id)):Promise.resolve();
async function localImage(img,id){const file=await getPhoto(id);if(!file)return false;const url=URL.createObjectURL(file);img.onload=img.onerror=()=>URL.revokeObjectURL(url);img.src=url;return true;}
function placeholder(){const el=create('div','card-placeholder');el.append(icon('image'),create('span','','Kein Foto'));return el;}
function bestImage(c,img){const fallback=async()=>{img.onerror=null;if(c.photoId&&await localImage(img,c.photoId))return;if(img.parentNode)img.replaceWith(placeholder());};if(c.image&&/^https:\/\//.test(c.image)){img.onerror=fallback;img.src=c.image;}else fallback();}
function cardTile(c){
  const el=create('article','card-tile'+(c.favorite?' is-favorite':'')),open=create('button','card-open');open.type='button';open.setAttribute('aria-label',c.name+' – Details öffnen');open.onclick=()=>openDetail(c.id);
  const art=create('div','card-art'),img=create('img');img.alt=c.name;img.loading='lazy';art.append(img);
  const info=create('div','card-info');info.append(create('b','',c.name),create('small','',[c.set,c.number].filter(Boolean).join(' · ')||'Manuell erfasst'),create('small','',variantLabel(c)),create('div','card-price',Number.isFinite(c.price)?money(c.price)+' / Karte':'Preis offen'));
  open.append(art,info);const heart=create('button','heart'+(c.favorite?' on':''));heart.type='button';heart.setAttribute('aria-label',(c.favorite?'Favorit entfernen: ':'Als Favorit markieren: ')+c.name);heart.setAttribute('aria-pressed',String(!!c.favorite));heart.append(icon(c.favorite?'heart-filled':'heart'));heart.title=c.favorite?'Favorit entfernen':'Als Favorit markieren';heart.onclick=()=>toggleFavorite(c.id);
  el.append(open,heart);if(c.quantity>1||c.status==='trade'||c.status==='sale')el.append(create('span','tile-badge',c.status==='trade'?'Tausch · ×'+c.quantity:c.status==='sale'?'Verkauf · ×'+c.quantity:'×'+c.quantity));bestImage(c,img);return el;
}
function empty(node,title,message,action){const el=create('div','empty');el.append(icon('grid'),create('b','',title),create('span','',message));if(action){const b=create('button','btn primary',action.label);b.type='button';b.onclick=action.run;el.append(b);}node.replaceChildren(el);}
function fill(node,list,title='Noch keine Karten',message='Füge deine erste Karte hinzu.'){node.replaceChildren();if(!list.length){empty(node,title,message,{label:'Karte hinzufügen',run:()=>go('add')});return;}const f=document.createDocumentFragment();list.forEach(c=>f.append(cardTile(c)));node.append(f);}
function updateCard(id,patch,action='Karte bearbeitet'){const c=cards.find(x=>x.id===id);if(!c)return false;return commit(cards.map(x=>x.id===id?{...x,...patch}:x),albums,historyFor(c,action));}
function duplicateGroups(){const groups=new Map();cards.forEach(c=>{const key=duplicateKey(c);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c);});return [...groups.values()].filter(g=>g.length>1);}
function filteredCards(){const q=norm($('search').value),orderMap=new Map(cards.map((c,i)=>[c.id,i]));const dupIds=new Set(duplicateMode?duplicateGroups().flat().map(c=>c.id):[]);return cards.filter(c=>{
  if(q&&!norm([c.name,c.set,c.number,c.tags,c.notes,c.rarity].join(' ')).includes(q))return false;
  if(duplicateMode&&!dupIds.has(c.id))return false;
  if(filter==='favorites'&&!c.favorite||filter==='priced'&&!Number.isFinite(c.price)||filter==='unpriced'&&Number.isFinite(c.price)||['trade','sale'].includes(filter)&&c.status!==filter)return false;
  if($('filterSet').value&&c.set!==$('filterSet').value)return false;
  if($('filterLanguage').value&&c.language!==$('filterLanguage').value)return false;
  const v=$('filterVariant').value;if(v&&!(v==='1st Edition'?edition(c)==='first':v==='Shadowless'?shadowless(c):finish(c)===v))return false;return true;
}).sort((a,b)=>{switch($('sort').value){case'name':return a.name.localeCompare(b.name,'de');case'value':return (b.price??-1)-(a.price??-1);case'number':return collectorId(a.number).localeCompare(collectorId(b.number),'de',{numeric:true});case'quantity':return b.quantity-a.quantity;default:return (orderMap.get(b.id)||0)-(orderMap.get(a.id)||0);}});}
function render(){
  const count=cards.reduce((sum,c)=>sum+(Number(c.quantity)||1),0),priced=cards.filter(c=>Number.isFinite(c.price));
  $('count').textContent=count;$('unique').textContent=cards.length;$('albumCount').textContent=albums.length;$('total').textContent=priced.length?money(priced.reduce((sum,c)=>sum+c.price*c.quantity,0)):'–';
  $('priceCoverage').textContent=priced.length+' / '+cards.length;$('favoriteCount').textContent=cards.filter(c=>c.favorite).length;
  const costs=cards.filter(c=>Number.isFinite(c.purchasePrice));$('costTotal').textContent=costs.length?money(costs.reduce((n,c)=>n+c.purchasePrice*c.quantity,0)):'–';
  const fs=$('filterSet'),prev=fs.value;fs.replaceChildren(new Option('Alle Sets',''));[...new Set(cards.map(c=>c.set).filter(Boolean))].sort().forEach(s=>fs.add(new Option(s,s)));fs.value=prev;
  fill($('recent'),[...cards].reverse().slice(0,4),'Deine Sammlung beginnt hier','Fotografiere eine Karte oder erfasse sie manuell.');
  const filtered=filteredCards();$('resultCount').textContent=filtered.length+' Einträge · '+filtered.reduce((n,c)=>n+c.quantity,0)+' Karten'+(duplicateMode?' · Dubletten':'');
  fill($('cards'),filtered,cards.length?'Keine passenden Karten':'Deine Sammlung ist bereit',cards.length?'Ändere die Suche oder setze die Filter zurück.':'Erfasse deine erste Karte.');$('cards').classList.toggle('list-view',$('collectionView').value==='list');
  fill($('favoriteCards'),cards.filter(c=>c.favorite).reverse(),'Deine Highlights warten','Markiere eine Karte mit dem Herz-Symbol.');
  renderAlbums();renderWishlist();updateAlbumSelect();renderProfile();updateBackupStatus();
}
function go(id){if(!$(id)?.classList.contains('view'))return;currentView=id;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);if(b.dataset.view===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(location.hash&&location.hash.slice(1)!==id)history.pushState(null,'','#'+id);else history.replaceState(null,'','#'+id);window.scrollTo({top:0,behavior:'instant'});render();}
document.querySelectorAll('[data-view],[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view||b.dataset.go)));
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
for(const id of ['search','sort','filterSet','filterLanguage','filterVariant','collectionView'])$(id).addEventListener(id==='search'?'input':'change',render);
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();});
$('resetFilters').onclick=()=>{filter='all';duplicateMode=false;$('search').value='';['filterSet','filterLanguage','filterVariant'].forEach(id=>$(id).value='');$('clearDuplicateFilter').classList.add('hidden');document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));render();};
$('showDuplicates').onclick=()=>{duplicateMode=true;$('clearDuplicateFilter').classList.remove('hidden');render();toast(duplicateGroups().length+' Dubletten-Gruppen mit gleicher Sprache, Variante und Zustand');};
$('clearDuplicateFilter').onclick=()=>{duplicateMode=false;$('clearDuplicateFilter').classList.add('hidden');render();};
// Albums, including a real nine-pocket paged binder.
function updateAlbumSelect(){const s=$('albumSelect'),v=s.value;s.replaceChildren(new Option('Kein Album',''));albums.forEach(a=>s.add(new Option(a.name,a.id)));s.value=v;}
function renderAlbums(){const list=$('albumList');list.replaceChildren();for(const a of albums){const related=PokeCore.albumCards(cards,a);const b=create('button','album-card');b.type='button';b.append(icon(['book','star','folder','heart','sparkles'].includes(a.emoji)?a.emoji:'book'),create('b','',a.name),create('small','',related.length+' Einträge · '+related.reduce((n,c)=>n+c.quantity,0)+' Karten'));b.onclick=()=>openAlbum(a.id);list.append(b);}if(!albums.length)empty(list,'Dein erstes Album','Ordne deine Karten nach Sets, Themen oder Tauschplänen.',{label:'Album erstellen',run:()=>openAlbumEditor()});if(currentAlbum){const a=albums.find(x=>x.id===currentAlbum);if(!a){backAlbums();return;}$('albumTitle').textContent=a.name;const related=PokeCore.albumCards(cards,a);$('albumStats').textContent=related.length+' Einträge · '+Math.max(1,Math.ceil(related.length/9))+' Seiten';$('albumCards').classList.toggle('hidden',binderMode);$('binder').classList.toggle('hidden',!binderMode);if(binderMode)renderBinder(related);else fill($('albumCards'),related,'Dieses Album wartet auf Karten','Ordne Karten über ihre Detailansicht diesem Album zu.');}}
