function backAlbums(){currentAlbum=null;$('albumList').classList.remove('hidden');$('newAlbum').classList.remove('hidden');$('albumDetail').classList.add('hidden');}
$('backAlbums').onclick=backAlbums;$('newAlbum').onclick=()=>openAlbumEditor();$('editAlbum').onclick=()=>openAlbumEditor(currentAlbum);
for(const [id,mode]of [['albumGrid',false],['albumBinder',true]])$(id).onclick=()=>{binderMode=mode;$('albumGrid').classList.toggle('active',!mode);$('albumBinder').classList.toggle('active',mode);renderAlbums();};
function renderBinder(list){const pages=Math.max(1,Math.ceil(list.length/9));binderIndex=Math.min(Math.max(0,binderIndex),pages-1);const page=$('binderPage');page.replaceChildren();for(let i=0;i<9;i++){const c=list[binderIndex*9+i];const pocket=create(c?'button':'div','binder-slot');if(c){pocket.type='button';pocket.setAttribute('aria-label',c.name+' öffnen');const im=create('img');im.alt=c.name;pocket.append(im,create('b','',c.name));pocket.onclick=()=>openDetail(c.id);bestImage(c,im);}else pocket.textContent=String(binderIndex*9+i+1).padStart(2,'0');page.append(pocket);}$('binderCounter').textContent='Seite '+(binderIndex+1)+' / '+pages;$('binderPrev').disabled=binderIndex===0;$('binderNext').disabled=binderIndex===pages-1;}
function turnPage(delta){binderIndex+=delta;renderAlbums();}$('binderPrev').onclick=()=>turnPage(-1);$('binderNext').onclick=()=>turnPage(1);
