function openAlbumEditor(id=null){albumEditId=id;const a=albums.find(x=>x.id===id);$('albumEditorTitle').textContent=a?'Album bearbeiten':'Album erstellen';$('albumEditorName').value=a?.name||'';$('albumEditorEmoji').value=['book','star','folder','heart','sparkles'].includes(a?.emoji)?a.emoji:'book';$('albumEditorDelete').classList.toggle('hidden',!a);$('albumEditor').showModal();}
$('albumEditorForm').onsubmit=e=>{e.preventDefault();const name=$('albumEditorName').value.trim();if(!name)return;if(albums.some(a=>norm(a.name)===norm(name)&&a.id!==albumEditId))return toast('Ein Album mit diesem Namen existiert bereits.');const a={...albums.find(x=>x.id===albumEditId),id:albumEditId||uid(),name,emoji:$('albumEditorEmoji').value};const next=albumEditId?albums.map(x=>x.id===albumEditId?a:x):[...albums,a];if(commit(cards,next)){$('albumEditor').close();toast('Album gespeichert');if(albumPickId)openAlbumPicker(albumPickId);}};
