 ['Anzahl','× '+c.quantity],['Zustand',c.condition],['Sprache',c.language],['Variante',variantLabel(c)],['Seltenheit',c.rarity],['Status',{collection:'Sammlung',trade:'Tauschen',sale:'Verkaufen'}[c.status||'collection']],['Grading',c.grader?[c.grader,c.grade].filter(Boolean).join(' '):'Nicht bewertet'],['Referenzpreis / Karte',Number.isFinite(c.price)?money(c.price):'Nicht verfügbar'],['Gesamtreferenzwert',Number.isFinite(c.price)?money(c.price*c.quantity):'Nicht verfügbar'],['Kaufpreis / Karte',Number.isFinite(c.purchasePrice)?money(c.purchasePrice):'Nicht erfasst'],['Preisquelle',c.priceSource],['Preisstand',dateText(c.priceDate)],['Letzter Abruf',dateText(c.priceObservedAt)],['Alben',(c.albumIds||[]).map(id=>albums.find(a=>a.id===id)?.name).filter(Boolean).join(', ')],['Tags',c.tags]
