 const change=create('details','history-list');change.append(create('summary','','Änderungsverlauf'));const ul=create('ul');(extras.history[c.id]||[]).forEach(h=>ul.append(create('li','',dateText(h.at)+' · '+h.action)));if(!ul.childElementCount)ul.append(create('li','','Noch kein Verlauf'));change.append(ul);read.append(change);
