 throw Error(navigator.onLine?(last?.name==='AbortError'?'Datenquelle braucht zu lange – später erneut versuchen.':last?.message||'Datenquelle nicht erreichbar'):'Offline: diese Kartendaten wurden noch nicht geladen.');
