const nameIndexes=new Map(),searchSets=new Map();
async function searchSetIndex(lang){if(!searchSets.has(lang))searchSets.set(lang,json(apiUrl(lang,'sets')).then(list=>Array.isArray(list)?list:[]).catch(()=>[]));return searchSets.get(lang);}
