 renderMatches();$('matchStatus').textContent=candidates.length?'Bild, Nummer, Set und Sprache vergleichen und den passenden Treffer wählen.'+(errors.length?' Einige Datenquellen sind gerade nicht erreichbar.':''):errors.length?'Kartendatenbank nicht erreichbar. Manuelle Eingabe und lokale Fotos funktionieren weiterhin.':'Keine Treffer. Versuche nur die Nummer oder einen kürzeren Namen.';
