function updateScanQueue(){const more=scanFiles.length>1;$('scanQueue').classList.toggle('hidden',!more);$('scanQueueInfo').textContent=more?'Bild '+(scanIndex+1)+' / '+scanFiles.length+' · jedes Bild einzeln prüfen':'';$('scanNext').disabled=scanIndex>=scanFiles.length-1;}
function resetDraft(){$('manualReferenceHint').textContent='Optional, wenn kein passender Marktpreis vorhanden ist.';originalScanPhoto=null;$('restoreScan').disabled=true;const album=$('albumSelect').value;$('photoError').hidden=true;$('cardForm').reset();$('albumSelect').value=album;$('language').value=draftLanguage();$('condition').value=scanPrefs().defaultCondition;window.refreshCustomSelects?.();activePhoto=null;photoEpoch++;resetRecognition();for(const id of ['cropPhoto','clearPhoto','rotateScan','scan','visualCompare','autoCropNow','perspectivePhoto'])$(id).disabled=true;$('preview').classList.add('hidden');$('preview').removeAttribute('src');$('cameraPhoto').value='';$('photo').value='';$('scanStatus').textContent='Foto aufnehmen oder Bild auswählen. Manuelle Eingabe funktioniert auch ohne Foto.';$('matchStatus').textContent='Suche nach Name oder Nummer. Prüfe den passenden Treffer.';draftDirty=false;}
$('scanNext').onclick=async()=>{if(scanIndex>=scanFiles.length-1)return;if(draftDirty&&!await confirmAction('Nächstes Bild öffnen?','Ungespeicherte Angaben zu diesem Bild werden verworfen.','Weiter'))return;resetDraft();scanIndex++;await selectScanFile(scanFiles[scanIndex]);};
$('clearPhoto').onclick=()=>{$('photoError').hidden=true;originalScanPhoto=null;$('restoreScan').disabled=true;activePhoto=null;photoEpoch++;resetRecognition();for(const id of ['cropPhoto','clearPhoto','rotateScan','scan','visualCompare','autoCropNow','perspectivePhoto'])$(id).disabled=true;$('preview').classList.add('hidden');$('preview').removeAttribute('src');$('photo').value='';$('cameraPhoto').value='';scanFiles=[];scanIndex=0;updateScanQueue();$('scanStatus').textContent='Foto entfernt. Du kannst die Karte manuell erfassen.';};
$('rotateScan').onclick=async()=>{if(!activePhoto)return toast('Wähle zuerst ein Foto.');const epoch=photoEpoch;let bmp;try{bmp=await decodePhoto(activePhoto);const canvas=document.createElement('canvas');canvas.width=bmp.height;canvas.height=bmp.width;const ctx=canvas.getContext('2d');ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(Math.PI/2);ctx.drawImage(bmp,-bmp.width/2,-bmp.height/2);const f=await canvasBlob(canvas);if(epoch===photoEpoch)setScannerImage(f);}catch(err){toast(err.message);}finally{bmp?.close();}};
$('cropPhoto').onclick=async()=>{if(!activePhoto)return toast('Wähle zuerst ein Foto.');cropBitmap?.close();cropBitmap=await decodePhoto(activePhoto);$('cropX').value=5;$('cropY').value=5;$('cropW').value=90;$('cropH').value=90;$('cropDialog').showModal();drawCrop();};
function cropBounds(){const x=Number($('cropX').value)/100,y=Number($('cropY').value)/100,w=Math.min(Number($('cropW').value)/100,1-x),h=Math.min(Number($('cropH').value)/100,1-y);return{x,y,w,h};}
function drawCrop(){if(!cropBitmap)return;const canvas=$('cropCanvas'),scale=Math.min(1,600/cropBitmap.width,500/cropBitmap.height);canvas.width=Math.round(cropBitmap.width*scale);canvas.height=Math.round(cropBitmap.height*scale);const ctx=canvas.getContext('2d'),{x,y,w,h}=cropBounds();ctx.drawImage(cropBitmap,0,0,canvas.width,canvas.height);ctx.fillStyle='#0009';ctx.beginPath();ctx.rect(0,0,canvas.width,canvas.height);ctx.rect(x*canvas.width,y*canvas.height,w*canvas.width,h*canvas.height);ctx.fill('evenodd');ctx.strokeStyle='#f3f3ff';ctx.lineWidth=2;ctx.strokeRect(x*canvas.width,y*canvas.height,w*canvas.width,h*canvas.height);}
for(const id of ['cropX','cropY','cropW','cropH'])$(id).oninput=drawCrop;
let cropStart=null;function cropPoint(e){const r=$('cropCanvas').getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
$('cropCanvas').onpointerdown=e=>{cropStart=cropPoint(e);$('cropCanvas').setPointerCapture(e.pointerId);};
$('cropCanvas').onpointermove=e=>{if(!cropStart)return;const p=cropPoint(e);$('cropX').value=Math.min(cropStart.x,p.x)*100;$('cropY').value=Math.min(cropStart.y,p.y)*100;$('cropW').value=Math.max(.1,Math.abs(p.x-cropStart.x))*100;$('cropH').value=Math.max(.1,Math.abs(p.y-cropStart.y))*100;drawCrop();};
$('cropCanvas').onpointerup=$('cropCanvas').onpointercancel=()=>cropStart=null;
$('applyCrop').onclick=async()=>{if(!cropBitmap)return;const epoch=photoEpoch,source=cropBitmap,{x,y,w,h}=cropBounds(),canvas=document.createElement('canvas');canvas.width=Math.round(cropBitmap.width*w);canvas.height=Math.round(cropBitmap.height*h);if(canvas.width<60||canvas.height<60)return toast('Wähle einen größeren Kartenbereich.');canvas.getContext('2d').drawImage(cropBitmap,x*cropBitmap.width,y*cropBitmap.height,canvas.width,canvas.height,0,0,canvas.width,canvas.height);const blob=await canvasBlob(canvas);if(epoch!==photoEpoch||cropBitmap!==source||!$('cropDialog').open)return;setScannerImage(blob);$('cropDialog').close();toast('Zuschnitt übernommen');};
