// Local OCR. Third-party model downloads require a one-time choice.
function updateOCRInspector(){const area=$('ocrCandidates');area.replaceChildren();$('ocrRaw').textContent=lastOCR.raw||'Noch keine Texterkennung durchgeführt.';const seen=new Set();for(const line of [lastOCR.name,...(lastOCR.raw||'').split('\n')]){const v=(line||'').trim();if(v.length<3||v.length>60||seen.has(v)||seen.size>=12)continue;seen.add(v);const b=create('button','ocr-choice',v);b.type='button';b.onclick=()=>{$('name').value=v;invalidateMatch();};area.append(b);}if(lastOCR.number){const b=create('button','ocr-choice','Nummer: '+lastOCR.number);b.type='button';b.onclick=()=>{$('number').value=lastOCR.number;invalidateMatch();};area.prepend(b);}}
$('scannerInfo').onclick=()=>{$('ocrInspector').classList.toggle('hidden');updateOCRInspector();};
// Real image-based similarity across a bounded set of references, not a trained classifier.
function imageDescriptor(source){const canvas=document.createElement('canvas');canvas.width=24;canvas.height=32;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,24,32);const data=ctx.getImageData(0,0,24,32).data;const colors=[],gray=[];for(let i=0;i<data.length;i+=4){colors.push(data[i]/255,data[i+1]/255,data[i+2]/255);gray.push((data[i]*.299+data[i+1]*.587+data[i+2]*.114)/255);}const edges=[];for(let y=0;y<32;y++)for(let x=0;x<23;x++)edges.push(gray[y*24+x]>gray[y*24+x+1]);return{colors,edges};}
function visualSimilarity(a,b){let color=0,edge=0;for(let i=0;i<a.colors.length;i++)color+=Math.abs(a.colors[i]-b.colors[i]);for(let i=0;i<a.edges.length;i++)if(a.edges[i]===b.edges[i])edge++;return Math.round(100*(.6*(1-color/a.colors.length)+.4*edge/a.edges.length));}
async function remoteDescriptor(url){const img=new Image();img.crossOrigin='anonymous';img.src=url;let timer;const deadline=new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('Bild-Zeitlimit')),9000));try{await Promise.race([img.decode(),deadline]);return imageDescriptor(img);}finally{clearTimeout(timer);}}
async function visualCompare(){if(!activePhoto)return toast('Wähle zuerst ein Foto.');if(!candidates.length)return toast('Suche zuerst Kandidaten oder wähle ein Set für die Bildsuche.');const token=++visualToken,epoch=photoEpoch;const bitmap=await decodePhoto(activePhoto);const local=imageDescriptor(bitmap);bitmap.close();let done=0,ok=0;const work=candidates.filter(c=>c.image||c._imageReference).slice(0,250);if(!work.length)return toast('Für diese Kandidaten sind keine Referenzbilder verfügbar.');$('visualCompare').disabled=$('visualSet').disabled=true;$('cancelVisual').classList.remove('hidden');
 try{let cursor=0;async function run(){while(cursor<work.length){if(token!==visualToken||epoch!==photoEpoch)return;const c=work[cursor++];try{const descriptor=await remoteDescriptor(cardImageURL(c._imageReference||c.image));if(token!==visualToken||epoch!==photoEpoch)return;c._visual=visualSimilarity(local,descriptor);ok++;}catch{}done++;$('scanStatus').textContent='Lokaler Bildvergleich · '+done+' / '+work.length;}}await Promise.all([run(),run(),run()]);if(token!==visualToken||epoch!==photoEpoch)return;candidates.sort((a,b)=>PokeEngine.jointRank(b,activeSearchQuery())-PokeEngine.jointRank(a,activeSearchQuery()));renderMatches();$('scanStatus').textContent=ok?'Bildvergleich abgeschlossen: '+ok+' / '+work.length+' Bilder. Höchste Ähnlichkeit zuerst. Bild, Set und Nummer selbst bestätigen.':'Referenzbilder konnten nicht verglichen werden. Verbindung oder Bildfreigabe fehlt. Textsuche bleibt verfügbar.';
 }finally{$('visualCompare').disabled=!activePhoto;$('visualSet').disabled=false;$('cancelVisual').classList.add('hidden');}}
$('visualCompare').onclick=()=>visualCompare().catch(err=>toast(err.message));$('cancelVisual').onclick=()=>{visualToken++;$('scanStatus').textContent='Bildvergleich abgebrochen. Vorhandene Treffer bleiben verfügbar.';};
let setCatalog=[];
