$('loadSets').onclick=async()=>{const b=$('loadSets');b.disabled=true;try{const lang=apiLanguage(),list=await json(apiUrl(lang,'sets'));if(!Array.isArray(list))throw Error('Set-Katalog nicht verfügbar');setCatalog=list.map(s=>({...s,_lang:lang})).reverse();renderSetCatalog();toast(setCatalog.length+' Sets geladen');}catch(err){toast(err.message);}finally{b.disabled=false;}};
