// Backup and restore: validate everything before changing data, stage photos under new IDs.
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=create('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function asDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
function dataURLBlob(value){const [meta,body]=value.split(',');const decoded=atob(body),bytes=new Uint8Array(decoded.length);for(let i=0;i<decoded.length;i++)bytes[i]=decoded.charCodeAt(i);return new Blob([bytes],{type:meta.slice(5,meta.indexOf(';'))});}
async function fullBackup(){const b=$('export');b.disabled=true;try{const snapshot=structuredClone({cards,albums,extras});const photos={};let missing=0;for(const id of new Set([...snapshot.cards.flatMap(c=>[c.photoId,c.backPhotoId,c.customReferenceId]),...snapshot.albums.map(a=>a.coverPhotoId),...snapshot.extras.wishlist.flatMap(w=>[w.photoId,w.backPhotoId,w.customReferenceId])].filter(Boolean))){const photo=await getPhoto(id);if(photo)photos[id]=await asDataURL(photo);else missing++;}if(missing&&!await confirmAction('Fotos fehlen im Speicher',missing+' Kartenfoto(s) sind nicht lesbar. Ein Backup der übrigen Daten erstellen?','Trotzdem sichern'))return;const now=new Date().toISOString();const data={format:'pokescan-backup-v5',appVersion:'3.3',exportedAt:now,...snapshot,photos};downloadBlob(new Blob([JSON.stringify(data)],{type:'application/json'}),'PokeScan-Backup-'+now.slice(0,10)+'.json');commit(cards,albums,{...extras,lastBackupAt:now});toast(missing?'Backup erstellt. '+missing+' Foto(s) fehlen.':'Backup mit '+Object.keys(photos).length+' Fotos erstellt');}catch(err){toast('Backup fehlgeschlagen: '+err.message);}finally{b.disabled=false;}}
$('export').onclick=fullBackup;
async function restoreBackup(file){if(file.size>150*1024*1024)throw Error('Backup über 150 MB. Bitte ein kleineres Backup verwenden.');const raw=JSON.parse(await file.text()),validated=validateBackup(raw);const missing=new Set([...validated.cards.flatMap(c=>[c.photoId,c.backPhotoId,c.customReferenceId]),...validated.albums.map(a=>a.coverPhotoId),...(validated.extras?.wishlist||[]).flatMap(w=>[w.photoId,w.backPhotoId,w.customReferenceId])].filter(id=>id&&!Object.hasOwn(validated.photos,id))).size;const text=validated.cards.length+' Einträge, '+validated.albums.length+' Alben und '+Object.keys(validated.photos).length+' Fotos übernehmen? Die aktuelle Sammlung wird ersetzt. Sichere sie vorher.'+(missing?' '+missing+' Fotoreferenzen sind nicht im Backup; vorhandene lokale Fotos werden weiterverwendet, soweit verfügbar.':'');if(!await confirmAction('Backup wiederherstellen?',text,'Wiederherstellen'))return;
 const staged=[],idMap=new Map();try{for(const [oldId,data]of Object.entries(validated.photos)){const nextId=uid();const photo=dataURLBlob(data);await putPhoto(nextId,photo);staged.push(nextId);idMap.set(oldId,nextId);}const nextCards=validated.cards.map(c=>({...c,photoId:idMap.get(c.photoId)||c.photoId,backPhotoId:idMap.get(c.backPhotoId)||c.backPhotoId,customReferenceId:idMap.get(c.customReferenceId)||c.customReferenceId}));validated.albums=validated.albums.map(a=>({...a,coverPhotoId:idMap.get(a.coverPhotoId)||a.coverPhotoId}));const nextExtras=cleanExtras(validated.extras||{});nextExtras.wishlist=nextExtras.wishlist.map(w=>({...w,photoId:idMap.get(w.photoId)||w.photoId,backPhotoId:idMap.get(w.backPhotoId)||w.backPhotoId,customReferenceId:idMap.get(w.customReferenceId)||w.customReferenceId}));if(!persist(nextCards,validated.albums,nextExtras))throw Error('Speichern nicht möglich. Bisherige Sammlung bleibt erhalten.');cards=nextCards;albums=validated.albums;extras=nextExtras;currentAlbum=null;backAlbums();applyTheme();render();window.showScanSettings?.();toast('Backup wiederhergestellt');}catch(err){await Promise.all(staged.map(id=>deletePhoto(id).catch(()=>{})));throw err;}}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await restoreBackup(f);}catch(err){toast('Import fehlgeschlagen: '+err.message);}finally{e.target.value='';}};
function updateBackupStatus(){const at=extras.lastBackupAt;$('backupStatus').textContent=at?'Letzter erstellter Export: '+new Date(at).toLocaleString('de-DE'):'Noch kein Komplett-Backup erstellt.';const reminder=$('backupReminder'),old=!at||Date.now()-Date.parse(at)>7*86400000;reminder.classList.toggle('hidden',!cards.length||!old);if(old&&cards.length){reminder.replaceChildren(create('span','','Deine Sammlung ist lokal gespeichert. Zeit für ein Komplett-Backup.'));const b=create('button','btn ghost','Jetzt sichern');b.onclick=fullBackup;reminder.append(b);}}
$('csvExport').onclick=()=>{const escape=value=>{let s=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['Name','Set','Nummer','Sprache','Zustand','Finish','Auflage','Shadowless','Anzahl','Referenzpreis EUR','Kaufpreis pro Karte EUR','Status','Seltenheit','Tags','Notizen'],...cards.map(c=>[c.name,c.set,c.number,c.language,c.condition,finish(c),edition(c),shadowless(c)?'Ja':'Nein',c.quantity,c.price,c.purchasePrice,c.status,c.rarity,c.tags,c.notes])];downloadBlob(new Blob(['\uFEFF'+rows.map(r=>r.map(escape).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'PokeScan-Sammlung.csv');toast('CSV exportiert');};
// Profile, coherent color themes and a useful wishlist.
function initials(name){return(name||'PS').trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase();}
function renderProfile(){const p=extras.profile;$('topUsername').textContent=p.name||'Sammler';$('topAvatar').textContent=p.avatar?'':initials(p.name);$('topAvatar').style.backgroundImage=p.avatar?'url("'+p.avatar+'")':'';}
function applyTheme(){const theme=['violet','blue','green','rose','gold','teal','orange','slate','red','cyan','lime','indigo','peach','custom'].includes(extras.profile.theme)?extras.profile.theme:'violet';const pref=extras.profile.appearance||'dark';document.documentElement.dataset.theme=theme;document.documentElement.dataset.appearance=pref==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):pref;$('appearance').value=pref;document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();}
$('appearance').onchange=()=>{const next=structuredClone(extras);next.profile.appearance=$('appearance').value;if(commit(cards,albums,next))applyTheme();};
matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(extras.profile.appearance==='system')applyTheme();});
function openProfile(){const p=extras.profile;pendingProfileAvatar=p.avatar||null;$('profileInput').value=p.name||'Sammler';$('profileBio').value=p.bio||'';$('profileTheme').value=p.theme||'violet';$('profilePhoto').value='';updateProfilePreview();$('profileDialog').showModal();}
function updateProfilePreview(){const name=$('profileInput').value||'Sammler';$('profilePreviewName').textContent=name;$('profilePreview').textContent=pendingProfileAvatar?'':initials(name);$('profilePreview').style.backgroundImage=pendingProfileAvatar?'url("'+pendingProfileAvatar+'")':'';}
$('profileInput').oninput=updateProfilePreview;$('profileTrigger').onclick=$('profileEdit').onclick=openProfile;
$('profilePhoto').onchange=async e=>{const f=e.target.files[0];if(!f)return;let bmp;try{if(!f.type.startsWith('image/'))throw Error('Bitte ein Bild wählen');bmp=await decodePhoto(f);const canvas=document.createElement('canvas');canvas.width=canvas.height=160;const side=Math.min(bmp.width,bmp.height);canvas.getContext('2d').drawImage(bmp,(bmp.width-side)/2,(bmp.height-side)/2,side,side,0,0,160,160);pendingProfileAvatar=canvas.toDataURL('image/jpeg',.8);updateProfilePreview();}catch(err){toast(err.message);}finally{bmp?.close();}};
$('profileForm').onsubmit=e=>{e.preventDefault();const next=structuredClone(extras);next.profile={...next.profile,name:$('profileInput').value.trim()||'Sammler',bio:$('profileBio').value.trim(),theme:$('profileTheme').value,avatar:pendingProfileAvatar};if(commit(cards,albums,next)){applyTheme();$('profileDialog').close();toast('Profil gespeichert');}};
function renderWishlist(){const list=$('wishlistDisplay');list.replaceChildren();if(!extras.wishlist.length){empty(list,'Platz für deinen nächsten Fund','Speichere Wunschkarten mit Set und Zielbudget.',{label:'Wunschkarte hinzufügen',run:()=>$('wishDialog').showModal()});return;}for(const w of extras.wishlist){const row=create('div','wish-entry'),info=create('div');info.append(create('b','',w.name),create('small','',[w.set,Number.isFinite(w.budget)?'Zielbudget '+money(w.budget):''].filter(Boolean).join(' · ')));const actions=create('div');const search=create('button','btn secondary','Suchen');search.onclick=()=>{$('name').value=w.name;$('set').value=w.set||'';invalidateMatch();go('add');searchMatches().catch(err=>toast(err.message));};const remove=create('button','btn ghost','Entfernen');remove.onclick=()=>{const next=structuredClone(extras);next.wishlist=next.wishlist.filter(x=>x.id!==w.id);if(commit(cards,albums,next))toast('Wunsch entfernt',{label:'Rückgängig',run:()=>{const restored=structuredClone(extras);restored.wishlist.push(w);commit(cards,albums,restored);}});};actions.append(search,remove);row.append(info,actions);list.append(row);}}
$('addWish').onclick=()=>$('wishDialog').showModal();
$('wishForm').onsubmit=e=>{e.preventDefault();const name=$('wishName').value.trim();if(!name)return;const next=structuredClone(extras);next.wishlist.push({id:uid(),name,set:$('wishSet').value.trim(),budget:$('wishBudget').value===''?null:Number($('wishBudget').value)});if(commit(cards,albums,next)){$('wishDialog').close();$('wishForm').reset();toast('Wunschkarte gespeichert');}};
// PWA installation and update only after explicit in-app action; never clear user data.
let installPrompt=null,swRegistration=null,updateRequested=false;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installStatus').textContent='PokéScan kann als App auf deinem Gerät installiert werden.';});
$('installApp').onclick=async()=>{if(!installPrompt){$('installStatus').textContent=matchMedia('(display-mode: standalone)').matches?'PokéScan läuft bereits als installierte App.':'Öffne PokéScan in Chrome unter HTTPS. Wähle im Browser-Menü „App installieren“ oder „Zum Startbildschirm hinzufügen“. Auf iOS: Teilen → Zum Home-Bildschirm.';return;}await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;};
async function activateUpdate(reg){if(draftDirty&&!await confirmAction('Update installieren?','Ungespeicherte Scan-Angaben werden beim Neustart verworfen. Gespeicherte Karten bleiben erhalten.','Neu starten'))return;updateRequested=true;reg.waiting?.postMessage({type:'ACTIVATE_UPDATE'});}
$('refresh').onclick=async()=>{try{const reg=swRegistration||await navigator.serviceWorker?.getRegistration();if(!reg)throw Error('App bitte unter HTTPS / localhost öffnen und einmal neu laden');await reg.update();if(reg.waiting)await activateUpdate(reg);else $('updateStatus').textContent='Updateprüfung abgeschlossen. Falls ein Update bereitsteht, erscheint gleich ein Hinweis.';}catch(err){$('updateStatus').textContent='Updateprüfung: '+err.message;}};
function network(){$('network').textContent=navigator.onLine?'Online':'Offline · lokal';$('network').dataset.online=String(navigator.onLine);}window.addEventListener('online',network);window.addEventListener('offline',network);
$('diagnose').onclick=async()=>{const b=$('diagnose');b.disabled=true;const lines=['Sammlung: '+cards.length+' Einträge · '+albums.length+' Alben','Netzwerk: '+(navigator.onLine?'online':'offline')];try{const db=await photoDB;lines.push('Fotospeicher: '+(db?'verfügbar':'nicht verfügbar'));let ok=0,missing=0;for(const c of cards)if(c.photoId){if(await getPhoto(c.photoId))ok++;else missing++;}lines.push('Fotos: '+ok+' lesbar · '+missing+' fehlen');const estimate=await navigator.storage?.estimate();if(estimate)lines.push('Browserspeicher: '+(estimate.usage/1024/1024).toFixed(1)+' MB von ca. '+Math.round(estimate.quota/1024/1024)+' MB');if(navigator.storage?.persist)lines.push('Dauerhafter Speicher: '+(await navigator.storage.persist()?'genehmigt':'vom Browser nicht zugesichert'));if(navigator.onLine){await json(apiUrl('en','cards/base1-4'),{fresh:true});lines.push('TCGdex: erreichbar');}}catch(err){lines.push('Prüfung: '+err.message);}finally{$('diagnosticResult').replaceChildren(...lines.map(line=>create('p','',line)));b.disabled=false;}};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d&&!['confirmDialog','cardDialog'].includes(d.id)){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
window.addEventListener('beforeunload',e=>{if(draftDirty){e.preventDefault();e.returnValue='';}});
// A second tab must not silently overwrite a newer collection.
window.addEventListener('storage',e=>{if([KEY,ALBUM_KEY,EXTRA_KEY].includes(e.key)){cards=safeParse(KEY,[]);albums=safeParse(ALBUM_KEY,[]);extras=cleanExtras(safeParse(EXTRA_KEY,{}));applyTheme();render();if($('cardDialog').open&&!window.hasUnsavedCardEdit?.())showDetail();toast(window.hasUnsavedCardEdit?.()?'Sammlung aktualisiert. Deine offenen Eingaben bleiben erhalten.':'Sammlung aus einem anderen Tab aktualisiert.');}});
network();applyTheme();go(location.hash.slice(1)||'home');
if('serviceWorker'in navigator){let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading||!updateRequested)return;reloading=true;location.reload();});window.addEventListener('load',async()=>{requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'instant'}));try{swRegistration=await navigator.serviceWorker.register('./sw.js');const notify=()=>{if(swRegistration.waiting&&navigator.serviceWorker.controller)toast('Eine neue PokéScan-Version ist bereit.',{label:'Installieren',run:()=>activateUpdate(swRegistration)});};notify();swRegistration.addEventListener('updatefound',()=>{const worker=swRegistration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')notify();});});}catch{$('updateStatus').textContent='Offline-Installation derzeit nicht verfügbar. Bitte HTTPS verwenden.';}});}
